${UNIVERSAL_Variable_INPUT__TIMEAGGREGATION_RUNTIME} ( case when  PU_COUNT( CASE_TABLE(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}) in (${UNIVERSAL_Variable_INPUT__AUTOMATEDACTIVITIES_RUNTIME}) )>0 AND (PU_COUNT( CASE_TABLE(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ${UNIVERSAL_Variable_INPUT__USERTYPE_RUNTIME}  in (${UNIVERSAL_Variable_INPUT__AUTOMATEDUSERS_RUNTIME}) and ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}) in (${UNIVERSAL_Variable_INPUT__AUTOMATEDACTIVITIES_RUNTIME}) )
!=
PU_COUNT( CASE_TABLE(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}), ACTIVITY_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}) in (${UNIVERSAL_Variable_INPUT__AUTOMATEDACTIVITIES_RUNTIME}) ))
then CALC_THROUGHPUT (ALL_OCCURRENCE['Process Start'] TO ALL_OCCURRENCE['Process End'], REMAP_TIMESTAMPS(TIMESTAMP_COLUMN(${UNIVERSAL_Variable_INPUT__ACTIVITYTABLE_RUNTIME}) ,  MINUTES,       WEEKDAY_CALENDAR (${UNIVERSAL_Variable_INPUT__CALENDARWEEK_RUNTIME}))) / (CASE WHEN '${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}' = 'DAYS' THEN 1440 WHEN '${UNIVERSAL_Variable_INPUT__TIMESCALE_RUNTIME}' = 'HOURS' THEN 60 ELSE 1 END )
else NULL end )
